mapper.select:
SELECT
	COUNT(*) AS TOTAL_CNT,
	SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT,
	SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT,
	SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT,
	SUM(CASE WHEN A.STATUS_CD = '4' OR A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS PENDING_CNT
FROM dbo.TMN_MINWON A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = #{GBN}
  AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')


		AND A.DONG_ID = #{DONG_ID}
		AND A.LINE_GBN = #{LINE_GBN}
		AND A.HO_ID  = #{HO_ID}


		AND A.DONG_ID = #{DONG_ID}
		AND A.LINE_GBN = #{LINE_GBN}

			AND A.HO_ID  = #{HO_ID} AND A.LINE_NO = #{LINE_NO}



		AND A.MINWON_AREAR_SEQ  = #{MINWON_AREAR_SEQ}

SELECT
	A.OFFICE_CODE			AS OFFICE_CODE,
	A.SLIP_NO 				AS SLIP_NO,
	A.MINWON_DATE 			AS MINWON_DATE,
	A.MINWON_GBN			AS MINWON_GBN,
	'[' + ISNULL(C.GBN_NAME, ' ') + ']' + CHAR(13) + CHAR(10) + ISNULL(A.DESCR, '') AS DESCR,
	A.STATUS_CD 			AS STATUS_CD,
	CASE WHEN A.STATUS_CD = '1' THEN '처리'
		WHEN A.STATUS_CD = '2' THEN '보류'
		WHEN A.STATUS_CD = '3' THEN '반려'
		WHEN A.STATUS_CD = '4' THEN '처리중'
		ELSE '미결' END 		AS STATUS_NAME,
	B.WORK_USER 			AS WORK_USER
FROM dbo.TMN_MINWON A
LEFT JOIN dbo.TMN_MINWON_WORK B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SLIP_NO = B.SLIP_NO AND A.MINWON_DATE = B.MINWON_DATE
LEFT JOIN TMN_MINWON_GBN C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MINWON_GBN = C.GBN_ID
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = #{GBN}
	AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')


			AND A.DONG_ID = #{DONG_ID}
			AND A.LINE_GBN = #{LINE_GBN}
			AND A.HO_ID  = #{HO_ID}


			AND A.DONG_ID = #{DONG_ID}
			AND A.LINE_GBN = #{LINE_GBN}

				AND A.HO_ID  = #{HO_ID} AND A.LINE_NO = #{LINE_NO}



			AND A.MINWON_AREAR_SEQ  = #{MINWON_AREAR_SEQ}


ORDER BY CONVERT(INT, A.MINWON_DATE) DESC, CONVERT(INT, A.SLIP_NO) DESC

update.if:
UPDATE A SET A.GBN = U.GBN, A.TIME_INPUT = U.TIME_INPUT, A.TIME = U.TIME, A.MINUTE = U.MINUTE, A.MINWON_NAME = U.MINWON_NAME, A.HP_NO = U.HP_NO, A.MINWON_GBN = U.MINWON_GBN, A.RECEIPT_USER = U.RECEIPT_USER, A.DESCR = U.DESCR, A.STATUS_CD = U.STATUS_CD FROM dbo.TMN_MINWON A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SLIP_NO} AS SLIP_NO, #{row.MINWON_DATE} AS MINWON_DATE, #{row.GBN} AS GBN, #{row.TIME_INPUT} AS TIME_INPUT, #{row.TIME} AS TIME, #{row.MINUTE} AS MINUTE, #{row.MINWON_NAME} AS MINWON_NAME, #{row.HP_NO} AS HP_NO, #{row.MINWON_GBN} AS MINWON_GBN, #{row.RECEIPT_USER} AS RECEIPT_USER, #{row.DESCR} AS DESCR, #{row.TITLE} AS TITLE, #{row.STATUS_CD} AS STATUS_CD
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.SLIP_NO = U.SLIP_NO AND A.MINWON_DATE = U.MINWON_DATE

mapper.select:
SELECT
	ISNULL(MAX(A.SLIP_NO), 0) AS SLIP_NO
FROM dbo.TMN_MINWON A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
  AND A.MINWON_DATE = #{MINWON_DATE}

SELECT
	CONVERT(VARCHAR, MAX(CONVERT(INT, A.SLIP_NO)))				AS SLIP_NO,
	A.MINWON_DATE 			AS MINWON_DATE
FROM dbo.TMN_MINWON A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = #{GBN} AND A.MINWON_DATE = #{MINWON_DATE}
	AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')


			AND A.DONG_ID = #{DONG_ID}
			AND A.LINE_GBN = #{LINE_GBN}
			AND A.HO_ID  = #{HO_ID}


			AND A.DONG_ID = #{DONG_ID}
			AND A.LINE_GBN = #{LINE_GBN}

				AND A.HO_ID  = #{HO_ID} AND A.LINE_NO = #{LINE_NO}



			AND A.MINWON_AREAR_SEQ  = #{MINWON_AREAR_SEQ}


GROUP BY A.MINWON_DATE

update.if:
UPDATE A SET A.MINWON_GBN = U.MINWON_GBN, A.STATUS_CD = U.STATUS_CD FROM dbo.TMN_MINWON A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SLIP_NO} AS SLIP_NO, #{row.MINWON_DATE} AS MINWON_DATE, #{row.MINWON_GBN} AS MINWON_GBN, #{row.STATUS_CD} AS STATUS_CD
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.SLIP_NO = U.SLIP_NO AND A.MINWON_DATE = U.MINWON_DATE

UPDATE A SET A.WORK_DATE = U.WORK_DATE, A.TIME_INPUT = U.TIME_INPUT, A.TIME = U.TIME, A.MINUTE = U.MINUTE, A.WORK_USER = U.WORK_USER, A.WORK_DESC = U.WORK_DESC, A.STATUS_CD = U.STATUS_CD, A.GOODS_OUTPUT_YN = U.GOODS_OUTPUT_YN FROM dbo.TMN_MINWON_WORK A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SLIP_NO} AS SLIP_NO, #{row.MINWON_DATE} AS MINWON_DATE, #{row.WORK_SEQ} AS WORK_SEQ, #{row.WORK_DATE} AS WORK_DATE, #{row.TIME_INPUT} AS TIME_INPUT, #{row.TIME} AS TIME, #{row.MINUTE} AS MINUTE, #{row.WORK_USER} AS WORK_USER, #{row.WORK_DESC} AS WORK_DESC, #{row.STATUS_CD} AS STATUS_CD, #{row.GOODS_OUTPUT_YN} AS GOODS_OUTPUT_YN
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.SLIP_NO = U.SLIP_NO AND A.MINWON_DATE = U.MINWON_DATE AND A.WORK_SEQ = U.WORK_SEQ

mapper.select:
SELECT
	ISNULL(MAX(A.WORK_SEQ), 0) AS WORK_SEQ
FROM dbo.TMN_MINWON_WORK A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE}
  AND A.MINWON_DATE = #{MINWON_DATE} AND A.SLIP_NO = #{SLIP_NO}

