) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.SLIP_NO = U.SLIP_NO AND A.MINWON_DATE = U.MINWON_DATE

UPDATE A SET A.DEL_YN = 'Y', A.DEL_ID = U.LOGINUSER_ID, A.DEL_NM = U.LOGINUSER_NAME, A.DEL_DT = (GETDATE()) FROM dbo.TMN_MINWON_WORK A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.SLIP_NO} AS SLIP_NO, #{row.MINWON_DATE} AS MINWON_DATE, #{row.WORK_SEQ} AS WORK_SEQ, #{row.LOGINUSER_ID} AS LOGINUSER_ID, #{row.LOGINUSER_NAME} AS LOGINUSER_NAME
